import json
from pydantic_ai import Agent
from pydantic_ai.exceptions import ToolError

class OrphanGuard:
    '''Mirror of openworker _interrupted_tool — no orphaned tool_calls.'''

    @staticmethod
    def check_messages(messages: list[dict]) -> None:
        '''Pre-flight: ensure every assistant tool_call has a matching tool result.'''
        pending: set[str] = set()
        for msg in messages:
            if msg.get('role') == 'assistant' and msg.get('tool_calls'):
                for tc in msg['tool_calls']:
                    pending.add(tc['id'])
            elif msg.get('role') == 'tool' and msg.get('tool_call_id'):
                pending.discard(msg['tool_call_id'])
        for orphan_id in pending:
            raise ToolError(json.dumps({  # visible in conversation, triggers retry
                'error': 'tool call not executed',
                'reason': 'orphaned — turn was interrupted',
                'tool_call_id': orphan_id,
            }))

@agent.hook
async def guard_orphans(run_ctx) -> None:
    OrphanGuard.check_messages(run_ctx.messages)
